      "parent": "A",
      "ja": "家具；家庭用品または家庭用設備；コーヒーひき；香辛料ひき；真空掃除機一般<br>このクラスにおいては，下記の用語は以下に示す意味で用いる:<br>―家具はイーゼルまたはスタンド，例．黒板用または製図テーブル，をも包含する。",
      "en": "FURNITURE; DOMESTIC ARTICLES OR APPLIANCES; COFFEE MILLS; SPICE MILLS; SUCTION CLEANERS IN GENERAL<br><br><u>NOTE</u><br><br>In this subclass, the following term is used with the meaning indicated: <br>\"furniture\" covers also easels or stands, e.g. for blackboards or  drawing tables.",
      "count": 0,
