      "level": 8,
      "parent": "A47L15/00",
      "ja": "｛制御プロセス，すなわち，制御の目的または目標によって特徴づけられた機械の動作を制御するプロセス（水の軟化または水の軟化再生の制御のためのものＡ４７Ｌ１５／４２２９；水位の制御のためのものＡ４７Ｌ１５／４２４４；悪臭または臭気の制御のためのものＡ４７Ｌ１５／４２７６；水温の制御のためのものＡ４７Ｌ１５／４２８７；水圧の制御のためのものＡ４７Ｌ１５／４２８９；瀬戸物または食器用器具の状態の制御のためのものＡ４７Ｌ１５／４２９５；洗浄水の状態の制御のためのものＡ４７Ｌ１５／４２９７）｝",
      "en": "{Controlling processes, i.e. processes to control the operation of the machine characterised by the purpose or target of the control (for control of water softening or water softener regeneration A47L15/4229; for control of water level A47L15/4244; for control of bad smells or odours A47L15/4276; for control of water temperature A47L15/4287; for control of water pressure A47L15/4289; for control of condition of crockery or tableware A47L15/4295; for control of condition of washing water A47L15/4297)}",
      "count": 492,
      "ipcCode": "A47L15/00",
      "coreCode": "A47L15/00",
      "note": "",
      "sourceFile": "cpc_A47L.txt",
      "kind": "cpc"
